<?php if ($payments === []): ?><p class="empty"><?= e(__('empty.payments')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(__('fields.number')) ?></th><th><?= e(__('fields.amount')) ?></th><th><?= e(__('fields.method')) ?></th><th><?= e(__('fields.date')) ?></th></tr></thead><tbody><?php foreach ($payments as $row): ?><tr><td><?= e($row['number']) ?></td><td><?= e(money($row['amount'], $row['currency'])) ?></td><td><?= e($row['method']) ?></td><td><?= e(format_date($row['paid_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
